        stream: 'Turu akış olarak alın: `stream: true`, OpenAI Responses biçiminde server-sent events ile yanıt verir. İlk olay çalıştırmayı ve oturumu adlandırır; bağlantı kopsa bile yukarıdaki çağrılarla takip edebilirsiniz. İstemci bağlantıyı keserse çalıştırma sürer; `on_disconnect: "cancel"` onu durdurur.',
        later: 'Sonraya bırakın ve düşük öncelikte çalıştırın: `class: "deferred"` ile `delay_seconds` (ya da `run_at`). Callback URL’sini kendi uç noktanızla değiştirin; API, herkese açık bir adrese çözümlenemeyen bir ana makineyi reddeder. `callback`, `secret` alanındaki imzalama sırrıyla imzalanır; imza `X-Cognipeer-Signature` başlığında gelir. `Idempotency-Key`, yeniden denenen bir isteğin aynı çalıştırmayı döndürmesini sağlar; isteğe özgü bir anahtar kullanın.',
