        list: 'Çalıştırmaları hangi API başlatmış olursa olsun, en yeniden eskiye listeleyin. `agent`, `status`, `class`, `session_id`, `trigger_id` ya da `channel` ile filtreleyin; sayfalamak için `after` kullanın.',
